-- id:       group-having-breached
-- title:    Departments with more than 3 complaints past SLA
-- concept:  GROUP BY + HAVING + aggregate
-- rubric:   6 · DML / aggregates
-- purpose:  Open complaints whose deadline has passed, grouped by department, keeping only the worst offenders.
-- GENERATED by web/scripts/export-queries.ts from src/lib/data/mock/lab.ts. Edit there, then run npm run db:queries.

SELECT d.department_name, COUNT(*) AS breached,
       ROUND(AVG(EXTRACT(EPOCH FROM now() - c.sla_deadline) / 3600), 1) AS avg_hours_overdue
FROM complaint c
JOIN department d USING (department_id)
WHERE c.status IN ('OPEN','ASSIGNED','IN_PROGRESS','REOPENED','ESCALATED')
  AND c.sla_deadline < now()
GROUP BY d.department_name
HAVING COUNT(*) > 3
ORDER BY breached DESC;
